style.css:
a[href]:link:not([style]):not([class]):not([id]):not([font]) {
  color: #0000FF;
}

[class] a[href]:link, [id] a[href]:link {
  color: inherit !important;
}

a[href]:visited:not([style]):not([class]):not([id]):not([font]) {
  color: #FF00BA;
}

[class] a[href]:visited, [id] a[href]:visited {
  color: inherit !important;
}
